{
  "steps": [
    {
      "id": "step-1",
      "goal": "Open every unread invoice email in ap@company.example and save each attachment under working/<run-id>/ before any ERP changes are made.",
      "allowed_tools": [
        "mail.list",
        "mail.read",
        "files.write"
      ],
      "done_criterion": "All unread invoice emails in ap@company.example have been opened and all their attachments are saved under working/<run-id>/."
    },
    {
      "id": "step-2",
      "goal": "Extract invoice fields (vendor name, invoice number, amount, purchase order, goods receipt, invoice date, payment terms) from each saved attachment; use vision for image-only scans, flag confidence, and record extracted data under working/<run-id>/extractions.",
      "allowed_tools": [
        "files.extract",
        "browser.navigate",
        "browser.screenshot",
        "files.write"
      ],
      "done_criterion": "Every saved attachment has extracted invoice fields and confidence flags recorded under working/<run-id>/extractions."
    },
    {
      "id": "step-3",
      "goal": "For each extracted vendor, verify the vendor exists and is not blocked in LedgerLite; record missing or blocked vendors as exceptions and exclude their invoices from filing.",
      "allowed_tools": [
        "erp.list_vendors",
        "erp.get_vendor",
        "files.write"
      ],
      "done_criterion": "Every extracted vendor has been checked in LedgerLite; all missing or blocked vendors are recorded as exceptions and their invoices are excluded from filing."
    },
    {
      "id": "step-4",
      "goal": "For each invoice with a valid vendor, match it to its purchase order and goods receipt, check for duplicates by vendor and invoice number, and record any duplicate or amount mismatch as an exception instead of filing.",
      "allowed_tools": [
        "erp.list_purchase_orders",
        "erp.get_purchase_order",
        "erp.get_goods_receipt",
        "erp.list_invoices",
        "erp.get_invoice",
        "files.write"
      ],
      "done_criterion": "Each eligible invoice has been matched to a purchase order and goods receipt and checked for duplicates; duplicates and amount mismatches are recorded as exceptions and excluded from filing."
    },
    {
      "id": "step-5",
      "goal": "File each validated, non-exception invoice in LedgerLite against its purchase order and goods receipt.",
      "allowed_tools": [
        "erp.file_invoice"
      ],
      "done_criterion": "All validated invoices are filed in LedgerLite with correct purchase order and goods receipt associations, amount, and status."
    },
    {
      "id": "step-6",
      "goal": "Prepare payment schedules for filed invoices per the spend-limit policy: schedule USD payments within limits, prepare payments above 10,000 USD through the over-spend-limit approval gate, and do not split payments.",
      "allowed_tools": [
        "erp.list_invoices",
        "erp.get_invoice",
        "erp.schedule_payment"
      ],
      "done_criterion": "A payment schedule is prepared for each filed invoice that should be paid; only USD payments are scheduled, no split payments are created, and any payment above 10,000 USD is prepared and held for the over-spend-limit approval gate."
    },
    {
      "id": "step-7",
      "goal": "Move each successfully processed source PDF or scan from working/<run-id>/ to the processed folder and record the destination path for each file.",
      "allowed_tools": [
        "files.move",
        "files.write"
      ],
      "done_criterion": "All source PDFs and scans from this run are moved to the processed folder and the destination path for each is recorded."
    },
    {
      "id": "step-8",
      "goal": "Verify in LedgerLite that each filed invoice record exists with the correct amount and status, and verify in the filesystem that each source document is archived in the processed folder.",
      "allowed_tools": [
        "erp.list_invoices",
        "erp.get_invoice",
        "files.list"
      ],
      "done_criterion": "LedgerLite contains correct invoice records for all filed invoices and files.list confirms each source document is present in the processed folder with no missing archived files."
    }
  ]
}
